    o = ord(ch)
    if o < 32 or (0x7f <= o < 0xa0):
        return 0
    # combining marks
    if o in (0xad,) :
        return 1
    import unicodedata
    if unicodedata.combining(ch):
        return 0
    if unicodedata.east_asian_width(ch) in ("W","F"):
        return 2
    return 1

def str_width(s):
