def visible_width(s):
    return str_width(strip_ansi(s))

# Rust usize parse errors
def rust_parse_usize(s):
    """Return int or raise ValueError with Rust message"""
    if s == "":
        raise ValueError("cannot parse integer from empty string")
    # Rust's FromStr for unsigned allows leading '+'
    t = s
    # check overflow > 2^64-1 roughly; python int unlimited
    # invalid digit if any char not digit (after optional leading +)
    body = t[1:] if t.startswith("+") else t
    if body == "" or not body.isdigit() or not all('0'<=c<='9' for c in body):
