class ParsedRange:
    def __init__(self, lower, upper, kind=None, mag=0, raw=""):
        self.lower=lower; self.upper=upper; self.kind=kind; self.mag=mag; self.raw=raw
    def __repr__(self):
        return f"ParsedRange({self.lower},{self.upper},{self.kind},{self.mag})"

def _parse_usize_or_msg(s, custom=None):
    try:
        return rust_parse_usize(s)
    except ValueError as ex:
        if custom:
            raise BatError(custom)
        raise BatError(str(ex))

def parse_line_range(spec, for_highlight=False):
    # returns ParsedRange with encoded lower/upper for highlight/normal use;
    # negative-end visible specs have kind marker for later resolution
    if spec == "":
        raise BatError("Empty line range")
