        v = _parse_usize_or_msg(spec)
        return ParsedRange(v, v, raw=spec)
    parts = spec.split(":")
    if len(parts) > 3:
        # observed: specs with empty components yield invalid digit, otherwise too-many
        if any(p=="" for p in parts):
            raise BatError("invalid digit found in string")
        raise BatError("Line range contained too many ':' characters. Expected format: 'N', 'N:M', 'N::C', or 'N:M:C'")
    if len(parts) == 2:
        a,b = parts
        if a=="" and b=="":
            raise BatError("cannot parse integer from empty string")
        if a=="":
