    if tok.startswith("--"):
        name=tok[2:].split("=",1)[0]
        return name in LONG_MAP
    if tok.startswith("-") and len(tok)>1:
        ch=tok[1]
        return ch in SHORT_MAP
    return None

ALLOW_HYPHEN = {'line_range','terminal_width'}

def get_value_from_next(tokens, i, spec, prog, parsed):
    """tokens[i] is current option token already consumed; spec needs a value in next position. Returns (value, next_i) or raises"""
    if i+1 >= len(tokens):
        missing_value_error(spec)
    nxt = tokens[i+1]
    if spec.dest in ALLOW_HYPHEN:
        return nxt, i+1
    known = is_known_flag_token(nxt)
    if known is True:
        missing_value_error(spec)
    if known is False:
        # unknown flaglike should be reported as unknown argument
        # determine display
        if nxt.startswith("--"):
            nm=nxt[2:].split("=",1)[0]
            # create fresh parsed copy? parsed currently does not include spec (we haven't added used)
            unknown_long_error(prog, nm, parsed, is_short=False)
        else:
            # short
            ch=nxt[1] if len(nxt)>1 else ''
            unknown_long_error(prog, ch, parsed, is_short=True, display_token=f"-{ch}")
        missing_value_error(spec)
    # known==None -> consumable
    return nxt, i+1

def parse_token_list(tokens, prog, mode='cli'):
    parsed=ParsedArgs()
    i=0
    after_dd=False
    while i < len(tokens):
        tok=tokens[i]
        if after_dd:
            parsed.files.append(tok); i+=1; continue
        if tok=="--":
            after_dd=True; i+=1; continue
        if tok.startswith("--") and len(tok)>2:
            if "=" in tok:
                name, inline_val = tok[2:].split("=",1)
                has_inline=True
            else:
                name, inline_val, has_inline = tok[2:], None, False
            spec=LONG_MAP.get(name)
            if spec is None:
                unknown_long_error(prog, name, parsed, is_short=False)
            if spec.dest=='version':
                if has_inline:
                    unexpected_value_error(prog, spec, inline_val, parsed)
                # immediate
                raise ClapExit(0, (VERSION+"\n").encode(), b"")
            if spec.kind in ('bool','count'):
                if has_inline:
                    unexpected_value_error(prog, spec, inline_val, parsed)
                if spec.dest=='help':
                    # long help immediate
                    if mode=='cli':
                        raise ClapExit(0, HELP_LONG.encode(), b"")
                    else:
                        raise ClapExit(0, HELP_SHORT.encode(), b"")
                parsed.add_used(spec)
                if spec.kind=='count':
                    parsed.counts[spec.dest]=parsed.counts.get(spec.dest,0)+1
                else:
                    parsed.bools.add(spec.dest)
                i+=1; continue
            # value kind
            if has_inline:
                val=inline_val
                invalid_value_error(spec, val)
                parsed.add_used(spec); parsed.set_value(spec,val); i+=1; continue
            else:
                # need next
                val, ni = get_value_from_next(tokens, i, spec, prog, parsed)
                invalid_value_error(spec, val)
                parsed.add_used(spec); parsed.set_value(spec,val); i=ni+1; continue
        elif tok.startswith("-") and len(tok)>1 and tok != "-":
            # short cluster
            j=1
            help_pending=False
            while j < len(tok):
                ch=tok[j]
                spec=SHORT_MAP.get(ch)
                if spec is None:
                    unknown_long_error(prog, ch, parsed, is_short=True, display_token=f"-{ch}")
                if spec.dest=='version':
                    raise ClapExit(0, (VERSION+"\n").encode(), b"")
                if spec.kind in ('bool','count'):
                    if spec.dest=='help':
                        help_pending=True
                        parsed.add_used(spec)
                        j+=1; continue
                    parsed.add_used(spec)
                    if spec.kind=='count':
                        parsed.counts[spec.dest]=parsed.counts.get(spec.dest,0)+1
                    else:
                        parsed.bools.add(spec.dest)
                    j+=1; continue
                # value short
                rest=tok[j+1:]
                if rest!="":
                    val=rest[1:] if rest.startswith("=") else rest
                    invalid_value_error(spec, val)
                    parsed.add_used(spec); parsed.set_value(spec,val)
                    j=len(tok); break
                else:
                    val, ni = get_value_from_next(tokens, i, spec, prog, parsed)
                    invalid_value_error(spec, val)
                    parsed.add_used(spec); parsed.set_value(spec,val)
                    i=ni  # will be incremented outer
                    j=len(tok); break
            if help_pending:
                raise ClapExit(0, HELP_SHORT.encode(), b"")
            i+=1; continue
        else:
            # positional
            parsed.files.append(tok); i+=1; continue
    return parsed

