# ---------- final config ----------
def env_value(name):
    v=os.environ.get(name)
    if v is None or v=="":
        return None
    return v

def validate_env_value(env_name_for_display_arg, spec_dest, value):
    # find spec
    spec=next(s for s in ARG_SPECS if s.dest==spec_dest)
    if spec.validator:
        reason=spec.validator(value, spec)
        if reason:
            txt=f"error: invalid value '{value}' for '{spec.signature()}': {reason}\n"
            raise ClapExit(2,b"",txt.encode())
    if spec.choices and value not in spec.choices:
        txt=f"error: invalid value '{value}' for '{spec.signature()}'\n  [possible values: {', '.join(spec.choices)}]\n"
        raise ClapExit(2,b"",txt.encode())
    return value

class FinalConfig:
    pass

def build_final(cli_parsed, source_parsed, prog, argv):
    cfg=FinalConfig()
    cfg.prog=prog
    cfg.cli=cli_parsed; cfg.source=source_parsed
    # merge helpers
    def present(dest, parsed):
        return dest in parsed.values or dest in parsed.bools or dest in parsed.counts
    def cli_has(dest): return present(dest, cli_parsed)
    def source_has(dest): return source_parsed is not None and present(dest, source_parsed)
    def get_scalar(dest, env_name=None, default=None):
        if cli_has(dest):
            return cli_parsed.values.get(dest, default)
        if env_name:
            ev=env_value(env_name)
            if ev is not None:
                spec=next(s for s in ARG_SPECS if s.dest==dest)
                validate_env_value(env_name, dest, ev)
                return ev
        if source_has(dest):
            return source_parsed.values.get(dest, default)
        # env fallback if cli/source missing but env set handled above; also if env set and no ... above
        return default
    def get_append(dest):
        out=[]
        if source_parsed: out.extend(source_parsed.get_list(dest))
        out.extend(cli_parsed.get_list(dest))
        return out
    def get_bool(dest):
        return (source_parsed is not None and dest in source_parsed.bools) or (dest in cli_parsed.bools)
    def get_count(dest):
        c=0
        if source_parsed: c+=source_parsed.counts.get(dest,0)
        c+=cli_parsed.counts.get(dest,0)
        return c
    cfg.get_scalar=get_scalar; cfg.get_append=get_append; cfg.get_bool=get_bool; cfg.get_count=get_count; cfg.present_cli=cli_has
    # scalar options
    cfg.language=get_scalar('language')
    cfg.fallback_syntax=get_scalar('fallback_syntax')
    cfg.diff_context_val=get_scalar('diff_context')
    cfg.diff_context=int(cfg.diff_context_val) if cfg.diff_context_val is not None else 2
    # tabs
    tabs_raw=get_scalar('tabs', 'BAT_TABS')
    cfg.tabs=int(rust_parse_usize(tabs_raw)) if tabs_raw is not None else None
    cfg.wrap_mode=get_scalar('wrap', default='auto')
    if get_bool('chop_long_lines'):
        cfg.wrap_mode='never'
    # terminal width
    cfg.terminal_width_raw=get_scalar('terminal_width','BAT_WIDTH')
    cfg.color_mode=get_scalar('color', default='auto')
    cfg.italic_text=get_scalar('italic_text', default='never')
    cfg.decorations_mode=get_scalar('decorations', default='auto')
    if get_bool('force_colorization'):
        cfg.color_mode='always'; cfg.decorations_mode='always'
    cfg.theme_opt=get_scalar('theme','BAT_THEME')
    cfg.theme_light_opt=get_scalar('theme_light','BAT_THEME_LIGHT', default='Monokai Extended Light')
    cfg.theme_dark_opt=get_scalar('theme_dark','BAT_THEME_DARK', default='Monokai Extended')
    cfg.nonprintable_notation=get_scalar('nonprintable_notation', default='unicode')
    cfg.binary_mode=get_scalar('binary', default='no-printing')
    cfg.squeeze_limit_raw=get_scalar('squeeze_limit')
    cfg.squeeze_limit=int(rust_parse_usize(cfg.squeeze_limit_raw)) if cfg.squeeze_limit_raw is not None else None
    cfg.strip_ansi_mode=get_scalar('strip_ansi', default='never')
    cfg.pager_opt=None  # computed later
    # pager resolution
    if cli_has('pager'):
        cfg.pager_opt=cli_parsed.values.get('pager')
    elif env_value('BAT_PAGER') is not None:
        cfg.pager_opt=os.environ['BAT_PAGER']
    elif source_has('pager'):
        cfg.pager_opt=source_parsed.values.get('pager')
    elif os.environ.get('PAGER'):
        cfg.pager_opt=os.environ.get('PAGER')
    else:
        cfg.pager_opt=None
    # bools & appends
    cfg.show_all=get_bool('show_all')
    cfg.diff=get_bool('diff')
    cfg.squeeze_blank=get_bool('squeeze_blank')
    if cfg.squeeze_limit is not None:
        cfg.squeeze_blank=True
    cfg.unbuffered=get_bool('unbuffered')
    cfg.quiet_empty=get_bool('quiet_empty')
