# ---------- text transforms ----------
def decode_utf8_char_at(data, i):
    """Return (char, length) if valid UTF-8 at i, else (None,1)"""
    b=data[i]
    if b < 0x80:
        return chr(b),1
    if 0xC2 <= b <= 0xDF:
        l=2
    elif 0xE0 <= b <= 0xEF:
        l=3
    elif 0xF0 <= b <= 0xF4:
        l=4
    else:
        return None,1
    if i+l > len(data):
        return None,1
    try:
        s=data[i:i+l].decode('utf-8')
        if len(s)!=1:
            return None,1
        return s,l
    except Exception:
        return None,1

def replace_nonprintable_bytes(data, tab_width_effective, notation='unicode'):
    """data: bytes of a line without trailing '\\n' (but may contain other controls etc). Returns str"""
    # tab handling inside loop using cursor visibility
    out=[]
    cursor=0
    i=0
    tw=tab_width_effective if tab_width_effective!=0 else 4
    while i < len(data):
        b=data[i]
        if b < 0x80:
            ch=chr(b); l=1
            if ch==' ':
                out.append('·'); cursor+=1; i+=1; continue
            if ch=='\t':
                # tab placeholder
                if tw==0: tw=4
                width_needed = tw - (cursor % tw)
                if width_needed==1:
                    out.append('↹')
                else:
                    out.append('├' + '─'*(width_needed-2) + '┤')
                cursor+=width_needed; i+=1; continue
            if ch=='\n':
                # should not happen usually (line split), but represent
                if notation=='caret':
                    out.append('^J')
                else:
                    out.append('␊')
                cursor+=1; i+=1; continue
            if ch=='\r':
                if notation=='caret':
                    out.append('^M'); cursor+=2
                else:
                    out.append('␍'); cursor+=1
                i+=1; continue
            if b < 0x20 or b==0x7f:
                if notation=='caret':
                    if b==0x7f:
                        s='^?'
                    else:
                        s='^'+chr(b+64)
                    out.append(s); cursor+=len(s)
                else:
                    # unicode control picture U+2400+b, DEL is U+2421 (0x2400+0x7f? 0x247f no) special
                    if b==0x7f:
                        out.append('␡')
                    else:
                        out.append(chr(0x2400+b))
                    cursor+=1
                i+=1; continue
            out.append(ch); cursor+=1; i+=1; continue
        else:
            ch,l = decode_utf8_char_at(data,i)
            if ch is None:
                s=f"\\x{b:02X}"
                out.append(s); cursor+=len(s); i+=1; continue
            else:
                # valid unicode char >127
                s=f"\\u{{{ord(ch):x}}}"
                out.append(s); cursor+=len(s); i+=l; continue
    return ''.join(out)

def replace_nonprintable_trailing_newline(data_with_newline, tab_width, notation):
    # helper not used: lines are stored without newline, printer appends symbol manually
    return replace_nonprintable_bytes(data_with_newline, tab_width, notation)

def expand_tabs_text(text, tab_width):
    if tab_width==0:
        return text
    out=[]; cursor=0; i=0
    # text may contain ANSI escapes: treat them as zero width, carry through
    while i<len(text):
        if text[i]=='\x1b':
            m=ANSI_RE.match(text,i)
            if m:
                out.append(m.group(0)); i=m.end(); continue
        ch=text[i]
        if ch=='\t':
            width_needed = tab_width - (cursor % tab_width)
            out.append(' '*width_needed); cursor+=width_needed; i+=1; continue
        out.append(ch); cursor+=char_width(ch); i+=1
    return ''.join(out)

def expand_tabs_in_highlighted(highlighted, tab_width, plain_text_line):
    """Original expands tabs on original line before highlighting, so token text turns into spaces.
    Our highlighters generate tokens from line containing \t which would be emitted as \t in tokens.
    Simpler upper-level: highlighters are called on a line whose tabs are already expanded if tab_width !=0.
    """
    return highlighted

