                    if b==0x7f:
                        out.append('␡')
                    else:
                        out.append(chr(0x2400+b))
                    cursor+=1
                i+=1; continue
            out.append(ch); cursor+=1; i+=1; continue
        else:
            ch,l = decode_utf8_char_at(data,i)
            if ch is None:
                s=f"\\x{b:02X}"
                out.append(s); cursor+=len(s); i+=1; continue
            else:
                # valid unicode char >127
                s=f"\\u{{{ord(ch):x}}}"
                out.append(s); cursor+=len(s); i+=l; continue
    return ''.join(out)

def replace_nonprintable_trailing_newline(data_with_newline, tab_width, notation):
    # helper not used: lines are stored without newline, printer appends symbol manually
    return replace_nonprintable_bytes(data_with_newline, tab_width, notation)

def expand_tabs_text(text, tab_width):
    if tab_width==0:
        return text
    out=[]; cursor=0; i=0
    # text may contain ANSI escapes: treat them as zero width, carry through
    while i<len(text):
        if text[i]=='\x1b':
