            if m:
                out.append(m.group(0)); i=m.end(); continue
        ch=text[i]
        if ch=='\t':
            width_needed = tab_width - (cursor % tab_width)
            out.append(' '*width_needed); cursor+=width_needed; i+=1; continue
        out.append(ch); cursor+=char_width(ch); i+=1
    return ''.join(out)

def expand_tabs_in_highlighted(highlighted, tab_width, plain_text_line):
    """Original expands tabs on original line before highlighting, so token text turns into spaces.
    Our highlighters generate tokens from line containing \t which would be emitted as \t in tokens.
    Simpler upper-level: highlighters are called on a line whose tabs are already expanded if tab_width !=0.
    """
    return highlighted

