def check_cross_conflicts(prog, source_parsed, cli_parsed):
    if source_parsed is None: return
    # Build fake parsed with source used in order
    fake=ParsedArgs()
    for spec_dest in source_parsed.used:
        spec=next(s for s in ARG_SPECS if s.dest==spec_dest)
        fake.add_used(spec)
    # now iterate cli used, check against fake (which includes source plus cli so far)
    for spec_dest in cli_parsed.used:
        spec=next(s for s in ARG_SPECS if s.dest==spec_dest)
        # only trigger if partner was in source (not already within cli which was checked)
        partners=CONFLICT_MAP.get(spec_dest, [])
        for partner_dest in partners:
            if partner_dest in source_parsed.used:
                check_conflict(prog, fake, spec)
        fake.add_used(spec)

# ---------- git changes ----------
def get_git_changes(file_path):
    """Return dict line_no->marker char ('+','~','_','‾') or {} if no modifications vs index.
    Uses `git` CLI if available. file_path is a filesystem path (as given, relative to cwd)."""
    try:
        # Discover repo root / git dir
        # Use git status? We need index version. Approach:
        # git diff-index? Compare index blob to worktree file lines using git diff --no-index? Simpler: get index file content via git show :path relative to repo root.
        # Determine repo root and relative path
        dir_for_file = os.path.dirname(os.path.abspath(file_path)) if os.path.dirname(file_path) else os.getcwd()
        # git rev-parse --show-toplevel in that dir
        r=subprocess.run(["git","-C",dir_for_file,"rev-parse","--show-toplevel"], capture_output=True, text=False)
        if r.returncode!=0:
            return {}
        root=r.stdout.decode('utf-8','surrogateescape').strip()
        abs_file=os.path.abspath(file_path)
        try:
            rel=os.path.relpath(abs_file, root)
        except Exception:
            return {}
        if rel.startswith(".."):
            return {}
        # Index version: git show :<rel> (path with colon syntax). If not in index (untracked/staged new file? staged file is in index equal to worktree if no unstaged changes, so also no changes; untracked not in index -> {})
        r2=subprocess.run(["git","-C",root,"show",f":{rel}"], capture_output=True)
        if r2.returncode!=0:
            return {}
        old_bytes=r2.stdout
        try:
            new_bytes=Path(file_path).read_bytes()
        except Exception:
            return {}
        # If identical, {}
        if old_bytes==new_bytes:
            return {}
        # Decode lossily? Bat compares lines of file content (after...?). Use utf-8 lossy lines keeping line content without trailing newline; compare sequences.
        def split_lines(b):
            # Lines split on \n, stripping trailing \r? git diff treats lines including newline; to emulate difflib on line strings, keep \n attached except last.
            if b==b"":
                return []
            parts=b.split(b'\n')
            lines=[]
            for idx,part in enumerate(parts):
                if idx < len(parts)-1:
                    lines.append(part+b'\n')
                else:
                    if part!=b"":
                        lines.append(part)
            return lines
        old_lines=split_lines(old_bytes); new_lines=split_lines(new_bytes)
        # Use difflib SequenceMatcher (autojunk False)
        sm=difflib.SequenceMatcher(a=old_lines,b=new_lines,autojunk=False)
        changes={}
        for tag,i1,i2,j1,j2 in sm.get_opcodes():
            if tag=='equal': continue
            if tag=='insert':
                for j in range(j1,j2):
                    changes[j+1]='+'
            elif tag=='replace':
                for j in range(j1,j2):
                    changes[j+1]='~'
            elif tag=='delete':
                # mark adjacent new line
                if j1==0:
