    def _highlight_showall_transformed(self, content):
        # content is transformed string including possibly ␊ at end, ·, tab placeholders, escapes, control pics.
        hl=Highlighter(self.language, self.ctx.theme_name, self.ctx.truecolor, italic_always=False, use_color=True)
