        def tok(text, role):
            if not text: return ''
            style=self.ctx.theme_palette.get(role, self.ctx.theme_palette.get('fg',''))
            if self.cfg.italic_text!='always': style=strip_italic(style)
            if style=='': return text
            return f"\x1b[{style}m{text}\x1b[0m"
        out=[]; i=0
        # token categories scanning transformed content
        while i < len(content):
            # escape sequences \x.., \u{...}
            m=re.match(r'\\x[0-9A-Fa-f]{2}|\\u\{[0-9a-fA-F]+\}', content[i:])
            if m:
                out.append(tok(m.group(0),'comment')); i+=len(m.group(0)); continue
            ch=content[i]
            if ch=='·':
                out.append(tok(ch,'builtin')); i+=1; continue
            if ch=='↹':
                out.append(tok(ch,'number')); i+=1; continue
            if ch=='├':
                # until ┤
                j=content.find('┤', i)
