                    out.append(tok(content[i:j+1],'number')); i=j+1; continue
            if ch=='␊':
                out.append(tok(ch,'keyword')); i+=1; continue
            if ch=='␍':
                out.append(tok(ch,'string')); i+=1; continue
            if ch in ('␀','␇','␈','␛'):
                out.append(tok(ch,'function')); i+=1; continue
            if '\u2400' <= ch <= '\u2426' or ch=='␡':
                out.append(tok(ch,'fg')); i+=1; continue
            if content.startswith('^', i):
                # care notation two chars ^X
                if i+1<len(content) and content[i+1] not in (' ',):
                    two=content[i:i+2]
                    # classify by char after ^
                    after=content[i+1]
                    # map ^@,^G,^H,^[ as function, ^M string, ^J keyword
                    if two=='^J': role='keyword'
                    elif two=='^M': role='string'
                    elif two in ('^@','^G','^H','^['): role='function'
                    else: role='fg'
                    out.append(tok(two, role)); i+=2; continue
            # regular run: collect until special
            j=i
            while j < len(content):
                if re.match(r'\\x[0-9A-Fa-f]{2}|\\u\{', content[j:]): break
                cj=content[j]
                if cj in ('·','↹','├','␊','␍','␀','␇','␈','␛') or ('\u2400' <= cj <= '\u2426') or cj=='␡': break
                if cj=='^' and j>i: break
                if cj=='^' and j==i: break
                j+=1
            if j==i: # single char fallback
                out.append(tok(content[i],'fg')); i+=1
            else:
                out.append(tok(content[i:j],'fg')); i=j
        return ''.join(out)

