    # ---- panel helpers ----
    def panel_segments(self, line_no=None, change_char=None, mode='content'):
        # mode content/header(blank)/snip/continuation blank
        segs=[]
        if 'numbers' in self.styles and self.show_deco:
            if mode=='snip':
                segs.append(" ...")
            elif mode in ('header','continuation'):
                segs.append("    ")
            else:
                # number formatting width 4, may expand
                segs.append(f"{line_no:4d}")
        if self.changes_enabled and self.show_deco:
            if mode=='content':
                segs.append(change_char if change_char else ' ')
            else:
                segs.append(' ')
        return segs
    def compute_panel_width(self):
        if not self.show_deco:
            return 0
        segs=self.panel_segments(line_no=1, mode='content')
        # width = sum lengths + number of segs (each followed by space)
        w=sum(len(s)+1 for s in segs)
        return w
    def panel_prefix(self, line_no=None, change_char=None, mode='content'):
        if not self.show_deco:
            return ''
        segs=self.panel_segments(line_no, change_char, mode)
        has_grid='grid' in self.styles
        if has_grid and segs:
            if mode=='snip':
                base=''.join(s+' ' for s in segs)
                return base + "│ "
            else:
                base=''.join(s+' ' for s in segs)
                return base + "│ "
        else:
            if mode=='snip':
                return ' '.join(segs)
            else:
                return ''.join(s+' ' for s in segs)
    def colored_panel_prefix(self, line_no=None, change_char=None, mode='content'):
        # returns colored version of prefix if use_color: grid/numbers styles applied per piece
        # Original coloring: numbers segment colored grid, then space plain, change char colored by type, space plain, grid char colored + space colored? Let's parse: content line color example: \x1b[38;5;246m   1\x1b[0m \x1b[31m_\x1b[0m \x1b[38;5;246m│\x1b[0m (space after grid not colored? It is: \x1b[38;5;246m│\x1b[0m plus space plain - Wait example: prefix after grid char: \x1b[0m + space (plain) then content. For header line: spaces... \x1b[38;5;246m│ \x1b[0mFile: bold... The header separator includes space inside colored wrapper: '│ ' both are grid style.
        # For simplicity if not use_color, return plain prefix
        prefix_plain=self.panel_prefix(line_no, change_char, mode)
        if not self.ctx.use_color:
            return prefix_plain
        # reconstruct precisely
        grid_style=self.ctx.theme_palette.get('grid','')
        segs=[]
        # rebuild with colors
        # Numbers segment
        parts=[]
        seg_list=self.panel_segments(line_no, change_char, mode)
        # Need map seg list order: numbers first if present, then changes
        idx=0
        has_numbers='numbers' in self.styles and self.show_deco
        has_changes=self.changes_enabled and self.show_deco
        has_grid='grid' in self.styles and self.show_deco and seg_list
        output=""
        if has_numbers:
            seg=seg_list[idx]; idx+=1
            if grid_style:
                output+=f"\x1b[{grid_style}m{seg}\x1b[0m "
            else:
                output+=seg+" "
        if has_changes:
            seg=seg_list[idx]; idx+=1
            # seg is one char; if mode content and change char present, color it: + green 32, ~ yellow 33, _/‾ red 31
            if mode=='content' and seg.strip()!='':
                cmap={'+':'32','~':'33','_':'31','‾':'31'}
                code=cmap.get(seg,'31')
                output+=f"\x1b[{code}m{seg}\x1b[0m "
            else:
                output+=seg+" " if False else (seg+" " if has_grid or True else seg)
                # For no-grid content, change segment followed by space plain
                # The above adds that.
            # In the case has_changes but no numbers and no grid, the plain prefix previously is seg+' '; output already
        if has_grid:
            if grid_style:
                # header/wrap modes: grid char includes trailing space inside colored wrapper
                if mode in ('header','continuation','snip'):
                    output+=f"\x1b[{grid_style}m│ \x1b[0m"
                else:
                    output+=f"\x1b[{grid_style}m│\x1b[0m "
            else:
                output+="│ "
        else:
            # no grid, output already has trailing spaces after each segment
            if not has_numbers and not has_changes:
                output=""
        # Special handling: for changes-only colored line without grid/number, original: marker colored + space, no-change line is two spaces (space + space). Our output: if has_changes and not has_numbers: we added seg colored or seg+" ". For empty change, seg=' ', output = "  " correct (first is seg space, second space). For colored marker, output = colored marker + " " correct.
        # For numbers+changes without grid: numbers colored + space, marker colored + space -- output matches.
        # If segs empty but grid: prefix is empty (no grid char) - happens grid-only lines: content prefix empty. Return that.
        if not seg_list:
            return ""
        return output

    def grid_line(self, junction):
        # junction top/mid/bottom char or None if panel width 0
        if not ('grid' in self.styles and self.show_deco):
            return None
        panel_w=self._panel_width_effective
        if panel_w>0:
            line="─"*panel_w + junction + "─"*(self.term_width-panel_w-1 if self.term_width>panel_w+1 else 0)
        else:
            line="─"*self.term_width
        if self.ctx.use_color:
            gs=self.ctx.theme_palette.get('grid','')
            if gs:
                # italic strip for grid? grid style has no italic.
                return f"\x1b[{gs}m{line}\x1b[0m"
            return line
        return line

