                else: main,suf=htext,""
                content=f"\x1b[1m{main}\x1b[0m{suf}"
                full=prefix+content
            elif kind=='file':
                # htext "File: NAME   <..>"
                rest=htext[len("File: "):]
                if "   <" in rest:
                    main,suf=rest.split("   <",1); suf="   <"+suf
                else: main,suf=rest,""
                content=f"File: \x1b[1m{main}\x1b[0m{suf}"
