        # wrapping header: if wrap mode... header wraps at term_width regardless? Earlier with wrap=never, header still wrapped. So do char wrap if full visible length > term_width.
        # But for colored, wrapping implementation should be based on visible width splitting ANSI-aware preserving styles (simple char wrap on ANSI string)
        if visible_width(full) <= self.term_width:
            return [full]
        # char wrap
        # Content area width: term_width - prefix_visible_width ; chunks of full: we need to produce physical lines each starting with same prefix (colored) then chunk of header content (post-prefix)
        # Extract prefix visible length
        prefix_vis=visible_width(prefix)
        content_width=self.term_width - prefix_vis
        if content_width<=0: content_width=self.term_width
        # Get content part after prefix (string)
        content_str=full[len(prefix):] if full.startswith(prefix) else full
        # If prefix colored differs length, use slicing by original full string after prefix length (we constructed). ok
        # Split content_str by visible width (ANSI aware)
        chunks=self._split_ansi_by_width(content_str, content_width)
        result=[]
        for idx,ch in enumerate(chunks):
            if idx==0:
                result.append(prefix+ch)
            else:
                # continuation prefix is same as header prefix (spaces + grid)
                result.append(prefix+ch)
        return result

    def _split_ansi_by_width(self, s, width):
        if width<=0: width=1
        chunks=[]; cur=''; cur_w=0; i=0
        while i < len(s):
            if s[i]=='\x1b':
                m=ANSI_RE.match(s,i)
                if m:
                    cur+=m.group(0); i=m.end(); continue
            ch=s[i]; w=char_width(ch)
            if cur_w + w > width and cur_w>0:
                chunks.append(cur); cur=''; cur_w=0
            cur+=ch; cur_w+=w; i+=1
        if cur!='' or not chunks:
            chunks.append(cur)
        return chunks

    def _snip_line(self):
        # Build line
        segs_present = bool(self.panel_segments(mode='snip'))
        prefix_plain=self.panel_prefix(mode='snip')
        # content width: term width - visible prefix (if grid: prefix includes │ plus space; if no grid: prefix is segments joined)
        # For grid, pattern is after prefix
        has_grid='grid' in self.styles and self.show_deco
        if has_grid and segs_present:
            prefix_width=visible_width(prefix_plain)
            content_width=self.term_width-prefix_width
            pattern=self._snip_pattern(content_width)
            line_plain=prefix_plain+pattern
        elif has_grid and not segs_present:
            content_width=self.term_width
            pattern=self._snip_pattern(content_width)
            line_plain=pattern
        else:
            # no grid: pattern after prefix (prefix is segments joined without trailing)
            prefix_width=visible_width(prefix_plain)
            content_width=self.term_width-prefix_width
            pattern=self._snip_pattern(content_width)
            line_plain=prefix_plain+pattern
        if self.ctx.use_color:
            gs=self.ctx.theme_palette.get('grid','')
            if gs:
                return f"\x1b[{gs}m{line_plain}\x1b[0m"
        return line_plain
    def _snip_pattern(self, content_width):
        if content_width<=0:
            return ""
        a=(content_width-1)//4
        L=content_width - (content_width % 2)
        if L<2:
            L=content_width
        b=(L - 2*a - 2)//2
        if b<0: b=0
        return "─ "*a + "8<" + " ─"*b

