# ---------- simple / loop-through rendering ----------
def split_raw_lines(raw):
    lines=[]; pos=0
    while pos < len(raw):
        idx=raw.find(b'\n', pos)
        if idx==-1:
            lines.append(raw[pos:]); break
        lines.append(raw[pos:idx+1]); pos=idx+1
    return lines

def render_simple_input(cfg, inp: InputData, ctx):
    """Return bytes output for non-interactive mode, subject to line ranges etc."""
    raw_lines=split_raw_lines(inp.raw)
    # For show-all, lines transformed using InputData show-all construction
    show_lines=None
    if cfg.show_all:
        tw=cfg.tabs if cfg.tabs is not None else 4
        show_lines=inp.make_lines_show_all(tw, cfg.nonprintable_notation)
    # visible
    total=len(raw_lines)
    if cfg.diff:
        visible_set=set()
        if inp.kind=='file' and inp.file_path:
            changes=get_git_changes(inp.file_path)
            for cl in changes.keys():
                for ln in range(max(1,cl-cfg.diff_context), cl+cfg.diff_context+1):
                    visible_set.add(ln)
        def is_visible(ln): return ln in visible_set
    else:
        if cfg.line_ranges_raw:
            parsed_visible=[parse_line_range(s, for_highlight=False) for s in cfg.line_ranges_raw]
            rs=LineRangeSet(parsed_visible)
            def is_visible(ln): return rs.is_visible(ln,total)
        else:
            def is_visible(ln): return True
    out_bytearray=bytearray()
    squeeze_count=0
    for idx, raw_line in enumerate(raw_lines,1):
        if not is_visible(idx):
            continue
        # squeeze decision based on original content empty
        content_no_term=raw_line
        if content_no_term.endswith(b'\n'): content_no_term=content_no_term[:-1]
        if content_no_term.endswith(b'\r'): content_no_term=content_no_term[:-1]
        is_empty=(content_no_term==b'')
        if cfg.squeeze_blank:
            limit=cfg.squeeze_limit if cfg.squeeze_limit is not None else 1
            if is_empty:
                squeeze_count+=1
                if squeeze_count>limit: continue
            else:
                squeeze_count=0
        if cfg.quiet_empty and inp.is_empty:
            continue
        if cfg.show_all and show_lines is not None:
            # show_lines index corresponds to line number (our construction splits similarly; if last line is trailing newline, show_lines count equals raw_lines count)
            if idx-1 < len(show_lines):
                sl=show_lines[idx-1]
                out_bytearray.extend(sl.content.encode('utf-8'))
                if sl.has_nl:
                    out_bytearray.extend(b'\n')
            else:
                out_bytearray.extend(raw_line)
        else:
            out_bytearray.extend(raw_line)
    return bytes(out_bytearray)

