# defined manually for parsing
class CacheParsed:
    def __init__(self):
        self.build=False; self.clear=False; self.blank=False; self.acknowledgements=False; self.source=None; self.target=None

def handle_cache(args, prog):
    # returns exit code, prints to stdout/stderr via Clap-like errors
    # Help handling sequential: -h/--help alone? cache '-h' outputs short, '--help' long.
    # sequential parse
    parsed=CacheParsed()
