        if tok in ('-h',):
            sys.stdout.write(CACHE_SHORT.replace("executable", prog, 1) if False else CACHE_SHORT.replace("Usage: executable", f"Usage: {prog}"))
            return 0
        if tok=='--help':
            sys.stdout.write(CACHE_LONG.replace("Usage: executable", f"Usage: {prog}"))
