            else:
                # unknown or bool with value -> unexpected argument/value errors for cache follows clap main pattern but simpler generic
                sys.stderr.write(f"error: unexpected argument '--{name}' found\n\nUsage: {prog} cache [OPTIONS]\n\nFor more information, try '--help'.\n"); return 2
