                sys.stderr.write(f"error: the argument '--build' cannot be used with '--clear'\n\nUsage: {prog} cache --build\n\nFor more information, try '--help'.\n"); return 2
            parsed.clear=True; used.append("--clear"); i+=1; continue
        if tok=='--blank':
