def read_config_tokens_from_file_strict(path):
    tokens=[]
    try:
        text=Path(path).read_text(encoding='utf-8', errors='surrogateescape')
    except Exception:
        return tokens
    for line in text.splitlines():
        stripped=line.strip()
        if not stripped: continue
        if stripped.startswith("#"): continue
        try:
            parts=shlex.split(line, comments=False, posix=True)
        except Exception:
            raise BatError("Could not parse configuration file")
        cleaned=[]
        for p in parts:
            if p.startswith("#"):
                break
            cleaned.append(p)
        tokens.extend(cleaned)
    return tokens

