def run_pager(pager_cmd, data_bytes, prog):
    # pager_cmd: string, parse shell words
    try:
        parts=shlex.split(pager_cmd)
    except Exception:
        parts=pager_cmd.split()
    if not parts:
        write_stdout_bytes(data_bytes); return True
    bin_name=parts[0]
    args=parts[1:]
    # Special less handling: if pager is "less" without extra args (command name exactly less or basename less? Original if pager binary is named less and no custom arguments provided via --pager/BAT_PAGER/PAGER? If the user provided "less -F", args not added. If default less (no args specified), add -R -K). Difference: how to know if less came from default vs explicit "less"? Both result in adding... observed explicit "--pager=less" also added -R -K. So rule: if basename of binary is 'less' and args is empty, add -R -K.
    if os.path.basename(bin_name)=="less" and len(args)==0:
        args=["-R","-K"]
    try:
        proc=subprocess.Popen(parts[0:1]+args, stdin=subprocess.PIPE)
    except OSError:
        # warning to stderr and output to stdout
        sys.stderr.write(f"\x1b[33m[bat warning]\x1b[0m: Pager '{bin_name}' not found, outputting to stdout instead\n")
