        write_stdout_bytes(data_bytes); return False
    try:
        proc.stdin.write(data_bytes); proc.stdin.close()
    except BrokenPipeError:
        pass
    except Exception:
        pass
    try:
        proc.wait()
    except Exception:
        pass
    return True

