def read_config_tokens_from_file_strict(path):
    tokens=[]
    try:
        text=Path(path).read_text(encoding='utf-8', errors='surrogateescape')
    except Exception:
        return tokens
    for line in text.splitlines():
        stripped=line.strip()
        if not stripped: continue
        if stripped.startswith("#"): continue
        try:
            parts=shlex.split(line, comments=False, posix=True)
        except Exception:
            raise BatError("Could not parse configuration file")
        cleaned=[]
        for p in parts:
            if p.startswith("#"):
                break
            cleaned.append(p)
        tokens.extend(cleaned)
    return tokens

def do_list_languages(cfg, languages, prog):
    # Coloring determined by use_color (color auto/always vs stdout tty)
    stdout_is_tty=False
    try: stdout_is_tty=sys.stdout.isatty()
    except: pass
    # Need PrinterContext style use_color: compute color mode separately without building full context? Use logic: If cfg.color_mode always -> true, auto -> tty and NO_COLOR etc.
    use_color=False
    if cfg.color_mode=='always': use_color=True
    elif cfg.color_mode=='auto' and stdout_is_tty and not (os.environ.get('NO_COLOR') not in (None,'')): use_color=True
    # If force_colorization flag present, cfg.color_mode already set always in build_final.
    if not use_color:
        out=''.join(f"{name}:{','.join(exts)}\n" for name,exts in languages)
        sys.stdout.write(out); return 0
    # colored: name padded to 26? Max name length? Sample column width 26 (  longest name ... 25? Let's check)
    # Determine term width for wrapping
    # Use cfg terminal width
    try:
        ctx_tmp_width=PrinterContext(cfg,languages,BASE_THEMES,stdout_is_tty).term_width
    except Exception:
        ctx_tmp_width=80
    term=ctx_tmp_width
    INDENT=26
    for name,exts in languages:
        # Name padded: f"{name:<26}"? If name length >=26, name+? Original for names longer than 25 , e.g., 'Bourne Again Shell (bash)' length 25? Padding to 26 gives one separating space.
        prefix=f"{name:<{INDENT}}"
        # If name longer than indent, prefix is name + space? Let's check long names in plain coloured list: names >26 like 'Bourne...' length 25 so fine. 'AsciiDoc (Asciidoctor)' 22. 'Fortran (Fixed Form)' etc. Max maybe 25. So safe.
        line_prefix=prefix
        current_visible=len(prefix)
        out_line=prefix
        first=True
        for ext in exts:
            coloured=f"\x1b[32m\x1b[32m{ext}\x1b[0m"
            ext_vis=len(ext)
            separator="" if first else ", "
            sep_vis=0 if first else 2
            # Wrap check: if current_vis + sep_vis + ext_vis > term: wrap to new line hanging indent.
            # But original wraps after separator: previous line ends with ", " then newline. Our check: if would exceed, we need emit separator first, then newline+ indent, then ext.
            if not first and current_visible + sep_vis + ext_vis > term:
                # add separator to current line, newline, indent
                sys.stdout.write(out_line + ", \n")
                out_line=" "*INDENT
                current_visible=INDENT
                # now ext on new line
                out_line+=coloured
                current_visible+=ext_vis
                first=False
                continue
            else:
                if not first:
                    out_line+=", "; current_visible+=2
                out_line+=coloured; current_visible+=ext_vis; first=False
        sys.stdout.write(out_line+"\n")
    return 0

def do_list_themes(cfg, languages, themes, prog):
    stdout_is_tty=False
    try: stdout_is_tty=sys.stdout.isatty()
    except: pass
    use_color=False
    if cfg.color_mode=='always': use_color=True
    elif cfg.color_mode=='auto' and stdout_is_tty and not (os.environ.get('NO_COLOR') not in (None,'')): use_color=True
    if not use_color:
        out=''.join(name+"\n" for name in themes)
        sys.stdout.write(out); return 0
    # coloured with previews for each theme using a Rust sample
    sample="  // Output the square of a number.\n  fn print_square(num: f64) {\n      let result = f64::powf(num, 2.0);\n      println!(\"The square of {num:.2} is {result:.2}.\");\n  }\n"
    # truecolor determination
    truecolor=os.environ.get('COLORTERM') in ('truecolor','24bit')
    for name in themes:
        is_default = (name=="Monokai Extended")
        title=f"\x1b[1m{name}\x1b[0m"
        if is_default:
            title+=" (default)"
        sys.stdout.write(title+"\n\n")
        # highlight sample with this theme
        hl=Highlighter("Rust", name, truecolor, italic_always=(cfg.italic_text=='always'), use_color=True)
        for line in sample.splitlines():
            sys.stdout.write(hl.highlight_line(line)+"\n")
        sys.stdout.write("\n")
    return 0

def run_pager(pager_cmd, data_bytes, prog):
    # pager_cmd: string, parse shell words
    try:
        parts=shlex.split(pager_cmd)
    except Exception:
        parts=pager_cmd.split()
    if not parts:
        write_stdout_bytes(data_bytes); return True
    bin_name=parts[0]
    args=parts[1:]
    # Special less handling: if pager is "less" without extra args (command name exactly less or basename less? Original if pager binary is named less and no custom arguments provided via --pager/BAT_PAGER/PAGER? If the user provided "less -F", args not added. If default less (no args specified), add -R -K). Difference: how to know if less came from default vs explicit "less"? Both result in adding... observed explicit "--pager=less" also added -R -K. So rule: if basename of binary is 'less' and args is empty, add -R -K.
    if os.path.basename(bin_name)=="less" and len(args)==0:
        args=["-R","-K"]
    try:
        proc=subprocess.Popen(parts[0:1]+args, stdin=subprocess.PIPE)
    except OSError:
        # warning to stderr and output to stdout
        sys.stderr.write(f"\x1b[33m[bat warning]\x1b[0m: Pager '{bin_name}' not found, outputting to stdout instead\n")
        write_stdout_bytes(data_bytes); return False
    except Exception:
        sys.stderr.write(f"\x1b[33m[bat warning]\x1b[0m: Pager '{bin_name}' not found, outputting to stdout instead\n")
        write_stdout_bytes(data_bytes); return False
    try:
        proc.stdin.write(data_bytes); proc.stdin.close()
    except BrokenPipeError:
        pass
    except Exception:
        pass
    try:
        proc.wait()
    except Exception:
        pass
    return True

