def stream_stdin_unbuffered(cfg, ctx, languages, input_specs):
    """Line-based streaming for --unbuffered with a single stdin input and no pager.
    Returns exit code or None to indicate fallback needed during first read.
    This is only invoked from main when appropriate."""
    # Determine display / hint
    idx=0
    if cfg.file_names:
        display=cfg.file_names[0]; hint=display
    else:
        display="STDIN"; hint=None
    accum=bytearray(); emitted=b""; language_error=None; first=True
    outbuf=sys.stdout.buffer
    while True:
        try:
            line=sys.stdin.buffer.readline()
        except Exception:
            line=b''
