def ansi_reemit_text(text):
    """Approximate bat's ANSI style re-emission for SGR sequences in input (no-colour interactive mode)."""
    if '\x1b' not in text:
        return text
    out=[]; i=0
    # style state
    fg=None; bg=None; bold=False; dim=False; italic=False; underline=False; link=None
    pending=False
    def reconstructed():
        parts=[]
        if fg: parts.append(f"\x1b[{fg}m")
        if bg: parts.append(f"\x1b[{bg}m")
        if bold: parts.append("\x1b[1m")
        if dim: parts.append("\x1b[2m")
        if italic: parts.append("\x1b[3m")
        if underline: parts.append("\x1b[4m")
        if link: parts.append(link)
        return ''.join(parts)
    while i < len(text):
        if text[i]=='\x1b':
            m=ANSI_RE.match(text,i)
            if m:
