# ---------- custom theme (tmTheme) parsing ----------
CUSTOM_THEME_PALETTES={}
def _hex_to_rgb(s):
    if not isinstance(s,str): return None
    s=s.strip()
    if not s.startswith('#'): return None
    h=s[1:]
    if len(h)>=6:
        try:
            return tuple(int(h[i:i+2],16) for i in (0,2,4))
        except Exception:
            return None
    if len(h)==3:
        try:
            return tuple(int(c*2,16) for c in h)
        except Exception:
            return None
    return None

def _rgb_to_lab(r,g,b):
    def pivot_rgb(v):
        v=v/255.0
        return v/12.92 if v<=0.04045 else ((v+0.055)/1.055)**2.4
    R=pivot_rgb(r); G=pivot_rgb(g); B=pivot_rgb(b)
    X=R*0.4124+G*0.3576+B*0.1805
    Y=R*0.2126+G*0.7152+B*0.0722
    Z=R*0.0193+G*0.1192+B*0.9505
    # D65
    X/=0.95047; Y/=1.0; Z/=1.08883
    def pivot_xyz(v):
        return v**(1/3) if v>0.008856 else (7.787*v)+(16/116)
    fx=pivot_xyz(X); fy=pivot_xyz(Y); fz=pivot_xyz(Z)
    return (116*fy-16, 500*(fx-fy), 200*(fy-fz))

def rgb_to_ansi256(r,g,b):
    # xterm palette
    palette=[]
    base=[(0,0,0),(128,0,0),(0,128,0),(128,128,0),(0,0,128),(128,0,128),(0,128,128),(192,192,192),(128,128,128),(255,0,0),(0,255,0),(255,255,0),(0,0,255),(255,0,255),(0,255,255),(255,255,255)]
    palette.extend(base)
    levels=[0,95,135,175,215,255]
    for rr in levels:
        for gg in levels:
            for bb in levels:
                palette.append((rr,gg,bb))
    for i in range(24):
        v=8+i*10; palette.append((v,v,v))
    target=_rgb_to_lab(r,g,b)
    best=0; bestd=None
    for idx,(rr,gg,bb) in enumerate(palette):
        lab=_rgb_to_lab(rr,gg,bb)
        d=sum((target[k]-lab[k])**2 for k in range(3))
        if bestd is None or d<bestd:
            bestd=d; best=idx
    return best

