    if 'italic' in fs: parts.append('3')
    if 'underline' in fs: parts.append('4')
    if mode=='tc':
        parts.append(f"38;2;{rgb[0]};{rgb[1]};{rgb[2]}")
    else:
        parts.append(f"38;5;{rgb_to_ansi256(*rgb)}")
    return ';'.join(parts)

def bg_style_from_hex(hexcol, mode='tc'):
    rgb=_hex_to_rgb(hexcol)
    if rgb is None: return ''
    if mode=='tc': return f"48;2;{rgb[0]};{rgb[1]};{rgb[2]}"
    return f"48;5;{rgb_to_ansi256(*rgb)}"

def parse_tmtheme_palette(text_bytes):
    """Return (name, palette_dict_by_mode) or (None,None) if invalid"""
    try:
        import plistlib
        obj=plistlib.loads(text_bytes)
    except Exception:
        return None,None
    if not isinstance(obj,dict): return None,None
    name=obj.get('name')
    settings=obj.get('settings')
    if not name or not isinstance(settings,list) or not settings:
        return None,None
    # global settings is first entry without scope
    global_settings={}
    scoped=[]
    for entry in settings:
        if not isinstance(entry,dict): continue
        s=entry.get('settings',{}) if isinstance(entry.get('settings',{}),dict) else {}
        scope=entry.get('scope')
        if scope is None:
            global_settings=s
        else:
            scoped.append((scope,s,entry.get('name','')))
    def find_color(scope_candidates, prefer_exact_prefix=True):
        # scope_candidates is list of scope strings to match; entry scope can be comma separated selectors
        best=None
        for cand in scope_candidates:
            for scope_str,s,entry_name in scoped:
                selectors=[sel.strip() for sel in str(scope_str).split(',')]
                for sel in selectors:
                    # selector may be descendant like "comment punctuation" - take first token
                    first=sel.split()[0] if sel.split() else sel
                    if first==cand or first.startswith(cand+'.') or cand.startswith(first+'.'):
                        return s
        return None
    role_scopes={
     'comment':['comment'],
     'keyword':['keyword.control','keyword'],
     'storage':['storage.type','storage'],
     'operator':['keyword.operator','keyword'],
     'function':['entity.name.function','support.function'],
     'builtin':['support.function','support'],
     'class':['entity.name.type.class','entity.name.class','entity.name.type','support.class'],
     'inherited':['entity.other.inherited-class'],
     'type':['support.type','entity.name.type'],
     'parameter':['variable.parameter'],
     'string':['string'],
     'number':['constant.numeric','constant'],
     'constant':['constant.language','constant'],
     'tag':['entity.name.tag'],
     'attribute':['entity.other.attribute-name'],
     'css_property':['support.type.property-name'],
     'css_tag':['entity.name.tag'],
     'heading':['markup.heading'],
     'bold':['markup.bold'],
     'italic':['markup.italic'],
     'md_code':['markup.raw','string'],
     'link_url':['markup.underline.link'],
     'yaml_key':['entity.name.tag.yaml','support.type.property-name.yaml','entity.name'],
     'json_key':['support.type.property-name.json','entity.name'],
    }
    palettes={}
    for mode in ('tc','ansi256'):
        pal={}
        fg_hex=global_settings.get('foreground')
        pal['fg']=style_from_hex(fg_hex,'',mode) if fg_hex else ''
        for role,cands in role_scopes.items():
            entry=find_color(cands)
            if entry and entry.get('foreground'):
                pal[role]=style_from_hex(entry.get('foreground'), entry.get('fontStyle',''), mode)
            else:
                pal[role]=pal['fg']
        # operator often keyword color
        # grid: gutterForeground or comment-ish
        grid_hex=global_settings.get('gutterForeground') or global_settings.get('gutter_foreground')
        if not grid_hex:
            entry=find_color(['comment'])
            grid_hex=entry.get('foreground') if entry else fg_hex
        if grid_hex:
            # grid style is color only (no fonts)
            rgb=_hex_to_rgb(grid_hex)
            if rgb:
                pal['grid']=(f"38;2;{rgb[0]};{rgb[1]};{rgb[2]}" if mode=='tc' else f"38;5;{rgb_to_ansi256(*rgb)}")
        hl_hex=global_settings.get('lineHighlight') or global_settings.get('line_highlight') or global_settings.get('selection')
        if hl_hex:
            pal['highlight_bg']=bg_style_from_hex(hl_hex, mode)
        else:
            pal['highlight_bg']=''
        palettes[mode]=pal
    return name,palettes
